async function loadStorage(){const host=$('storageBody');if(!host)return;host.innerHTML='<div class="field-hint">正在读取本机结果文件占用…</div>';try{const d=await api('/storage',{timeout:20000});const largest=d.largest?`${esc(d.largest.name)}（${bytesText(d.largest.size)}）`:'—';host.innerHTML=`${d.warn?`<div class="notice">结果文件已占用 ${bytesText(d.total_bytes)}，建议清理不再需要的记录或孤立文件。</div>`:''}<div class="summary report-metrics"><div class="report-metric"><div class="metric-label">结果文件合计</div><div class="metric-value">${bytesText(d.total_bytes)}<small> ${num(d.artifact_count,0)} 个</small></div><div class="metric-note">仅统计 run_*.jsonl 与 quality_run_*.json</div></div><div class="report-metric"><div class="metric-label">已被记录引用</div><div class="metric-value">${bytesText(d.referenced_bytes)}</div><div class="metric-note">删除对应任务记录才会一并删除</div></div><div class="report-metric"><div class="metric-label">孤立文件</div><div class="metric-value">${bytesText(d.orphan_bytes)}<small> ${num(d.orphan_count,0)} 个</small></div><div class="metric-note">没有任何记录引用，可安全清理</div></div><div class="report-metric"><div class="metric-label">最大单个文件</div><div class="metric-value" style="font-size:14px">${largest}</div><div class="metric-note">用于判断单次任务的结果规模</div></div></div><p class="report-section-sub">清理只删除“没有任何记录引用”的孤立文件；被引用的结果文件必须通过删除对应任务记录来删除，这样“删文件”和“删记录”始终是同一个可审计动作。</p><div class="report-footer-actions"><button class="btn" type="button" data-click-action="loadStorage">刷新</button><button class="btn danger" type="button" data-click-action="cleanupStorage" ${d.orphan_count?'':'disabled'}>清理孤立文件</button></div>${d.orphans?.length?`<div class="table-wrap report-wrap"><table class="report-table"><thead><tr><th>孤立文件</th><th>大小</th><th>最后修改</th></tr></thead><tbody>${d.orphans.map(x=>`<tr><td>${esc(x.name)}</td><td>${bytesText(x.size)}</td><td>${new Date(x.mtime*1000).toLocaleString('zh-CN',{dateStyle:'medium',timeStyle:'short'})}</td></tr>`).join('')}</tbody></table></div>`:''}`}catch(e){host.innerHTML=`<div class="auth-error">${esc(e.message)}</div>`}}
async function cleanupStorage(){if(!confirm('确认清理孤立结果文件？这些文件没有任何任务记录引用，删除后无法恢复。'))return;try{const d=await api('/storage/cleanup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({}) ,timeout:60000});toast(`已清理 ${num((d.removed||[]).length,0)} 个文件，释放 ${bytesText(d.freed_bytes)}`);loadStorage()}catch(e){toast(e.message)}}
