function updateKeyInputHint(){const input=$('api_key'),hint=$('keyInputHint'),n=input?.value?.length||0;if(!hint)return;if(window.secureStoreAvailable===false){hint.textContent='系统安全存储不可用；密钥仅供本次运行，重测时需重新填写。';return}if(n)hint.textContent=`已输入 ${n} 个字符；启动成功后会加密保存到 系统钥匙串。`;else if(window.savedApiKey)hint.textContent=`已保存密钥 ${window.savedApiKeyHint||''}；留空将直接复用，输入新值会覆盖。`;else hint.textContent='尚未保存密钥；输入后会加密保存到 系统钥匙串。'}
